#!/usr/bin/env pwsh
# Generated by Claude Opus 4.8 (claude.ai/code) · 2026-11-11
# Pester 5 tests for the sequencer library. Dependency-free: no docker, no network.
#   Invoke-Pester -Path ./tests

BeforeAll {
    $repo = Split-Path -Parent $PSScriptRoot
    Import-Module (Join-Path $repo 'src/lib/BackupCommon.psm1') -Force
    $script:TestsDir = $PSScriptRoot
    $script:Work = Join-Path ([System.IO.Path]::GetTempPath()) ("bkseqtest-" + [guid]::NewGuid().ToString('n'))
    New-Item -ItemType Directory -Force -Path $script:Work | Out-Null
}

AfterAll {
    if ($script:Work -and (Test-Path -LiteralPath $script:Work)) {
        Remove-Item -LiteralPath $script:Work -Recurse -Force -ErrorAction SilentlyContinue
    }
}

Describe 'event log and projection' {
    It 'appends and reads events' {
        $ev = Join-Path $Work 'events-1.jsonl'
        Add-BackupEvent -EventsPath $ev -Type 'run.start' -Props @{ runId = 'r1' }
        Add-BackupEvent -EventsPath $ev -Type 'step.end' -Props @{ svc = 'a'; step = 'dump'; status = 'ok'; durationSec = 3; runId = 'r1' }
        $events = Get-BackupEvents -EventsPath $ev
        $events.Count | Should -Be 2
        $events[0].type | Should -Be 'run.start'
    }

    It 'folds a per-service projection' {
        $ev = Join-Path $Work 'events-2.jsonl'
        Add-BackupEvent -EventsPath $ev -Type 'step.end' -Props @{ svc = 'a'; step = 'dump'; status = 'ok'; durationSec = 5 }
        Add-BackupEvent -EventsPath $ev -Type 'service.end' -Props @{ svc = 'a'; status = 'ok'; bytes = 2048 }
        $proj = Get-ServiceProjection -EventsPath $ev
        $proj['a'].lastBytes | Should -Be 2048
        $proj['a'].stepDurations['dump'] | Should -Be 5
        (Get-EstimatedServiceSeconds -Projection $proj -Service 'a') | Should -Be 5
    }
}

Describe 'single-instance lock' {
    It 'refuses a second holder, then frees' {
        $lock = Join-Path $Work 'seq.lock'
        (Enter-SequencerLock -LockPath $lock) | Should -BeTrue
        (Enter-SequencerLock -LockPath $lock) | Should -BeFalse
        Exit-SequencerLock -LockPath $lock
        (Enter-SequencerLock -LockPath $lock) | Should -BeTrue
        Exit-SequencerLock -LockPath $lock
    }
}

Describe 'time window' {
    It 'handles a normal daytime window' {
        Test-WithinWindow -Open '09:00' -Close '17:00' -Now ([datetime]'2026-01-01 12:00') | Should -BeTrue
        Test-WithinWindow -Open '09:00' -Close '17:00' -Now ([datetime]'2026-01-01 18:00') | Should -BeFalse
    }
    It 'handles a window that wraps past midnight' {
        Test-WithinWindow -Open '23:00' -Close '06:00' -Now ([datetime]'2026-01-01 02:00') | Should -BeTrue
        Test-WithinWindow -Open '23:00' -Close '06:00' -Now ([datetime]'2026-01-01 23:30') | Should -BeTrue
        Test-WithinWindow -Open '23:00' -Close '06:00' -Now ([datetime]'2026-01-01 12:00') | Should -BeFalse
    }
}

Describe 'path size measurement' {
    It 'returns 0 for a non-existent path' {
        Get-PathSizeBytes -Path (Join-Path $Work 'nope') | Should -Be 0
    }
    It 'returns 0 for an empty directory without throwing (regression, under Stop)' {
        $ErrorActionPreference = 'Stop'
        $d = Join-Path $Work 'empty-dir'
        New-Item -ItemType Directory -Force -Path $d | Out-Null
        { Get-PathSizeBytes -Path $d } | Should -Not -Throw
        Get-PathSizeBytes -Path $d | Should -Be 0
    }
    It 'returns 0 for a directory containing only subdirectories' {
        $d = Join-Path $Work 'subdirs-only'
        New-Item -ItemType Directory -Force -Path (Join-Path $d 'wip') | Out-Null
        Get-PathSizeBytes -Path $d | Should -Be 0
    }
    It 'sums file sizes recursively' {
        $d = Join-Path $Work 'with-files'
        New-Item -ItemType Directory -Force -Path (Join-Path $d 'sub') | Out-Null
        Set-Content -LiteralPath (Join-Path $d 'a.bin') -Value ('x' * 100) -NoNewline
        Set-Content -LiteralPath (Join-Path $d 'sub/b.bin') -Value ('y' * 50) -NoNewline
        Get-PathSizeBytes -Path $d | Should -Be 150
    }
}

Describe 'planning' {
    It 'puts mandatory first and preserves config order' {
        $cfg = @'
{ "window": { "open": "23:00", "close": "06:00" },
  "services": {
    "alpha": { "enabled": true,  "mandatory": false, "script": "x", "steps": [] },
    "beta":  { "enabled": true,  "mandatory": true,  "script": "x", "steps": [] },
    "gamma": { "enabled": false, "mandatory": false, "script": "x", "steps": [] },
    "delta": { "enabled": true,  "mandatory": false, "script": "x", "steps": [] }
  } }
'@ | ConvertFrom-Json
        $plan = Get-BackupPlan -Config $cfg
        @($plan.Service) | Should -Be @('beta', 'alpha', 'delta')
    }
}

Describe 'step execution' {
    It 'records duration and ok status' {
        $ev = Join-Path $Work 'step-ok.jsonl'
        (Invoke-BackupStep -EventsPath $ev -RunId 'r' -Service 's' -Step 'x' -Action { Start-Sleep -Milliseconds 10 }) | Should -Be 'ok'
        $end = Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'step.end' } | Select-Object -First 1
        $end.status | Should -Be 'ok'
        $end.durationSec | Should -BeGreaterOrEqual 0
    }
    It 'retries on failure then reports fail' {
        $ev = Join-Path $Work 'step-retry.jsonl'
        (Invoke-BackupStep -EventsPath $ev -RunId 'r' -Service 's' -Step 'x' -Action { throw 'nope' } -Retries 2 -BackoffSec 0) | Should -Be 'fail'
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'step.start' }).Count | Should -Be 3
    }
}

Describe 'spool lifecycle (wip -> stage -> ready)' {
    BeforeEach {
        $script:n = [guid]::NewGuid().ToString('n').Substring(0, 8)
        $script:ev = Join-Path $Work "lc-$n.jsonl"
        $script:root = Join-Path $Work "lc-$n"
        $script:paths = @{ BaseDir = $script:TestsDir; EventsPath = $script:ev; LockPath = ($script:root + '.lock'); SpoolRoot = $script:root }
    }

    It 'publishes a successful backup to ready/ and clears wip/stage' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        $runId = Invoke-BackupRun -Config $cfg -Paths $paths -Force -WarningAction SilentlyContinue
        $runId | Should -Not -BeNullOrEmpty
        (Test-Path (Join-Path $root 'ready/app/data.bin')) | Should -BeTrue
        (Test-Path (Join-Path $root 'ready/app/config.bin')) | Should -BeTrue
        (Test-Path (Join-Path $root 'wip/app')) | Should -BeFalse
        (Test-Path (Join-Path $root 'stage/app')) | Should -BeFalse
        $se = Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'app' } | Select-Object -First 1
        $se.status | Should -Be 'ok'
        $se.bytes | Should -BeGreaterThan 0
    }

    It 'does not publish a failed backup, but still runs recovery' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "boom", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -Force -WarningAction SilentlyContinue | Out-Null
        (Test-Path (Join-Path $root 'ready/app')) | Should -BeFalse
        $events = Get-BackupEvents -EventsPath $ev
        ($events | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'app' } | Select-Object -First 1).status | Should -Be 'fail'
        @($events | Where-Object { $_.type -eq 'step.start' -and $_.step -eq 'start' }).Count | Should -BeGreaterThan 0
    }

    It 'replaces an unconsumed previous backup and notifies' {
        New-Item -ItemType Directory -Force -Path (Join-Path $root 'ready/app') | Out-Null
        Set-Content -LiteralPath (Join-Path $root 'ready/app/old.bin') -Value 'old'
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -Force -WarningAction SilentlyContinue | Out-Null
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.replaced' }).Count | Should -BeGreaterThan 0
        (Test-Path (Join-Path $root 'ready/app/data.bin')) | Should -BeTrue
        (Test-Path (Join-Path $root 'ready/app/old.bin')) | Should -BeFalse
    }

    It 'reaps trash/ at run start' {
        New-Item -ItemType Directory -Force -Path (Join-Path $root 'trash/junk') | Out-Null
        Set-Content -LiteralPath (Join-Path $root 'trash/junk/f') -Value 'x'
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -Force -WarningAction SilentlyContinue | Out-Null
        (Test-Path (Join-Path $root 'trash/junk')) | Should -BeFalse
    }

    It 'sync-only (publishToReady=false) archives then leaves nothing in ready/' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "publishToReady": false,
    "syncArchive": { "script": "fixtures/mock-service.ps1", "env": {} },
    "steps": [ { "name": "dump", "resources": [] },
